  var LIM = { 'ls:cloud': 34, 'ls:router': 30, 'lb:tower': 26, 'ls:tower': 34, 'ls:module': 30, 'lb:up': 24, 'ls:up': 34, 'ls:nic': 34, 'ls:f50': 34, 'ls:phone': 34, 'p:rf': 30, 'p:usb': 24, 'p:cb': 24, 'p:bh': 36, 'sub': 44, 'ip': 40 }, lk;
