var KIND_ZH = { pc: '台式机', laptop: '笔记本', phone: '手机', tablet: '平板', tv: '电视', iot: '智能设备', printer: '打印机', console: '游戏机', camera: '摄像头', nas: '存储设备', speaker: '智能音箱', unknown: '未知设备' };
